import re,colorsys
p='src/styles.css';s=open(p).read()
def rgb(c):
 h=c[1:];h=''.join(x*2 for x in h) if len(h)==3 else h
 return [int(h[i:i+2],16)/255 for i in (0,2,4)] if len(h)>=6 else [0,0,0]
def replace_decl(m):
 prop,v=m.group(1),m.group(2)
 def change(c):
  h=c.group();r,g,b=rgb(h); l=(max(r,g,b)+min(r,g,b))/2;sat=max(r,g,b)-min(r,g,b)
  alpha=h[7:] if len(h)==9 else ''
  if prop.strip()=='color':
   if l<.32:return '#ecf1f8'+alpha
   if l<.65:return ('#8bbcff' if b-r>.15 else '#a3b2c5')+alpha
  elif prop.strip().startswith('background'):
   if l>.88:return '#101722'+alpha
   if l>.7:return '#182638'+alpha
  elif prop.strip().startswith('border') and l>.55:return '#293548'+alpha
  return h
 v=re.sub(r'#[\da-fA-F]{3,8}\b',change,v)
 if prop.strip().startswith('background'):v=re.sub(r'\bwhite\b','#101722',v)
 return prop+':'+v+';'
s=re.sub(r'([\w-]+)\s*:([^;{}]+);',replace_decl,s)
# Named text white stays white. Variables are deliberately explicit in the new theme.
open(p,'w').write(s)
