  { name: "Mercedes-Benz", slug: "mercedes", logo: "mercedes.svg", models: "EQS · A-Class", lens: "The premium experience", text: "Explore immersive displays, navigation and digital services.", number: "02" },
  { name: "BYD", slug: "byd", logo: "byd.png", models: "SEAL · SEAL 6 DM-i", lens: "The equipment proposition", text: "Explore cabin equipment, comfort and charging references.", number: "03" },
];
const lenses = [
  { title: "Passenger experience", positive: "Independent rear controls could give passengers more autonomy.", negative: "Extra screens could add cost, energy use and interface complexity.", question: "Which passenger tasks actually need another screen?" },
  { title: "Everyday usability", positive: "Fewer steps for frequent controls could make everyday interactions easier.", negative: "Moving controls could disrupt familiar habits and create new learning effort.", question: "Can BMW reduce interaction time without hiding useful controls?" },
  { title: "Premium value", positive: "A clearer equipment offer could make the value of a BMW easier to understand.", negative: "Adding standard equipment could reduce margin or increase the entry price.", question: "Which features matter enough for customers to choose BMW?" },
];

export default function Competitor() {
  const scope = useAppStore((s) => s.scope);
  const [brand, setBrand] = useState("All brands");
  const [market, setMarket] = useState<string>(scope.market);
  const [query, setQuery] = useState("");
  const [lens, setLens] = useState(0);
  const today = new Date().toISOString().slice(0, 10);
  const current = catalog.filter((r) => r.reference_status === "current_reference" && r.verified_on <= today && r.review_due_on >= today);
  const records = current.filter((r) => (brand === "All brands" || r.brand === brand) && (market === "All markets" || r.market === market) && `${r.model} ${r.passage} ${r.categories.join(" ")}`.toLowerCase().includes(query.toLowerCase()));
  const sourceCount = new Set(current.map((r) => r.source_uri)).size;
  const activeLens = lenses[lens];
  return (
    <div className="ci-page">
      <section className="ci-hero" aria-labelledby="ci-title">
        <IntelligenceShader className="ci-shader" />
        <div className="ci-hero-grid" aria-hidden="true" />
        <div className="ci-hero-copy">
          <div className="ci-kicker"><span /> 03 / COMPETITOR INTELLIGENCE</div>
          <h1 id="ci-title">Know the field.<br /><em>Define what’s next.</em></h1>
          <p>See what rivals offer. Understand the trade-offs.<br />Find a distinctive direction for BMW.</p>
          <a className="ci-hero-link" href="#competitor-evidence">Explore the evidence <ArrowDown size={17} /></a>
        </div>
        <div className="ci-orbit" aria-hidden="true">
          <div className="ci-orbit-ring ci-orbit-ring-outer" /><div className="ci-orbit-ring ci-orbit-ring-inner" />
          <div className="ci-orbit-core"><img src="/images/bmw-logo.svg" alt="" /></div>
          {brands.map((b) => <div className={`ci-orbit-brand ci-orbit-${b.slug}`} key={b.slug}><img src={`/images/competitors/${b.logo}`} alt="" /></div>)}
          <span className="ci-orbit-caption">A WIDER PERSPECTIVE.</span>
        </div>
        <div className="ci-hero-bottom"><span><ShieldCheck size={15} /> Official-source research</span><span>Curated library · reviewed 10 Oct 2026</span></div>
      </section>

      <div className="ci-context"><div><img src="/images/bmw-logo.svg" alt="BMW" /><span>YOUR FOCUS<strong>{scope.vehicle} <i>/</i> {scope.market} <i>/</i> {scope.powertrain}</strong></span></div><p>Technology references · segment and trim equivalence must be checked</p></div>
      <section aria-labelledby="ci-brands-heading">
        <div className="ci-section-heading"><div><span className="ci-kicker">THE COMPETITIVE LANDSCAPE</span><h2 id="ci-brands-heading">Three perspectives. New possibilities.</h2></div><span className="ci-counter">{current.length} reviewed records <i> / </i> {sourceCount} source pages</span></div>
        <div className="ci-brands">{brands.map((b) => <button key={b.slug} className={`ci-brand ci-brand-${b.slug} ${brand === b.name ? "is-selected" : ""}`} aria-pressed={brand === b.name} onClick={() => setBrand(brand === b.name ? "All brands" : b.name)}>
          <div className="ci-brand-top"><span>{b.number} / {b.name}</span>{brand === b.name ? <Check size={18} /> : <ArrowUpRight size={18} />}</div>
          <div className="ci-brand-art"><div className="ci-brand-halo" /><img src={`/images/competitors/${b.logo}`} alt={`${b.name} logo`} /></div>
          <div className="ci-brand-body"><span className="ci-models">{b.models}</span><h3>{b.lens}</h3><p>{b.text}</p></div>
          <div className="ci-brand-footer"><span>{current.filter((r) => r.brand === b.name).length} reviewed records</span><span>{brand === b.name ? "Selected" : "Explore brand"} <ChevronRight size={14} /></span></div>
        </button>)}</div>
      </section>

      <section className="ci-library" id="competitor-evidence" aria-labelledby="ci-library-heading">
        <div className="ci-section-heading"><div><span className="ci-kicker">FROM SIGNAL TO SOURCE</span><h2 id="ci-library-heading">Evidence, with the detail that matters.</h2></div><Layers3 size={24} /></div>
        <div className="ci-toolbar"><div className="ci-brand-filters" role="group" aria-label="Filter by competitor">{["All brands", ...brands.map((b) => b.name)].map((b) => <button key={b} aria-pressed={brand === b} className={brand === b ? "active" : ""} onClick={() => setBrand(b)}>{b}</button>)}</div>
          <label className="ci-market"><Globe2 size={15} /><select aria-label="Evidence market" value={market} onChange={(e) => setMarket(e.target.value)}>{["Europe", "United States", "China", "All markets"].map((m) => <option key={m}>{m}</option>)}</select></label>
        </div>
        <div className="ci-search-row"><label className="ci-search"><Search size={17} /><input aria-label="Search competitor evidence" placeholder="Search displays, charging, comfort…" value={query} onChange={(e) => setQuery(e.target.value)} /></label><span aria-live="polite">{records.length} records</span></div>
        <p className="ci-scope-note">{market === "Europe" ? "European references here cover the UK. Equipment may differ in other countries." : "References apply to the stated country, model and equipment only."} BMW trim fitment is not yet verified. This is a curated source library, not a live agent result.</p>
        <div className="ci-records">{records.length ? records.map((r) => <details className="ci-record" key={r.id}>
