import type { Source } from './live';
export type MarketTopic = 'Electrification' | 'Charging' | 'Digital experience' | 'Regional demand';
export interface MarketSeries {
  id: string; market: string; model: string; level: 'group' | 'model'; title: string;
  unit: string; evidence_id: string; yoy: number | null;
