}
export interface MarketSignal {
  id: string; title: string; topic: MarketTopic; market: string; geography: string;
  period: string; kind: string; headline: string; unit: string; summary: string;
  implication: string; evidence_id: string; published_on: string; verified_on: string;
}
export interface MarketDashboard {
  as_of: string; series: MarketSeries[]; signals: MarketSignal[]; evidence: Source[]; coverage: string[];
