cat > src/pages/Market.tsx <<'EOF'
import { useEffect, useId, useState } from 'react';
import { Link } from 'react-router-dom';
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { ArrowDownRight, ArrowRight, ArrowUpRight, BatteryCharging, Check, ChevronDown, Cpu, Globe2, LoaderCircle, Radar, RefreshCw, Sparkles, Zap } from 'lucide-react';
