import type { MarketDashboard, MarketTopic } from '../lib/api/market';
import './market.css';
const topics: {name: MarketTopic; icon: typeof Zap}[] = [{name:'Electrification',icon:Zap},{name:'Charging',icon:BatteryCharging},{name:'Digital experience',icon:Cpu},{name:'Regional demand',icon:Globe2}];
const regions = ['Europe','United States','China'] as const;
const number = (n:number) => new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(n);
function SourceDetails({source}:{source?:Source}) {
  if (!source) return null;
  return <details className="mt-source"><summary>Source & scope <ChevronDown size={14}/></summary><div><strong>{source.source_title}</strong><p>{source.locator}</p>{source.source_uri.startsWith('https://') && <a href={source.source_uri} target="_blank" rel="noreferrer">Read original source <ArrowUpRight size={13}/></a>}<ul>{source.caveats.map(c=><li key={c}>{c}</li>)}</ul></div></details>;
}
function RadarVisual({region}:{region:string}) {
  return <div className="mt-radar" aria-hidden="true"><div className="mt-radar-grid"/><div className="mt-orbit mt-orbit-outer"/><div className="mt-orbit mt-orbit-inner"/><div className="mt-radar-sweep"/><div className="mt-radar-core"><Radar size={32}/><span>{region}</span><small>MARKET PERSPECTIVE</small></div><i className="mt-radar-dot mt-dot-a"/><i className="mt-radar-dot mt-dot-b"/><i className="mt-radar-dot mt-dot-c"/><span className="mt-radar-caption">Signals. Context. Direction.</span></div>;
}
export default function Market() {
  const scope=useAppStore(s=>s.scope);
  const [region,setRegion]=useState<string>(scope.market);
  const [topic,setTopic]=useState<MarketTopic>('Electrification');
  const [signalIndex,setSignalIndex]=useState(0);
  const [data,setData]=useState<MarketDashboard|null>(null);
  const [runtime,setRuntime]=useState<Runtime|null>(null);
  const [error,setError]=useState('');
  const [requestError,setRequestError]=useState('');
  const [refresh,setRefresh]=useState(0);
  const [chartLevel,setChartLevel]=useState<'group'|'model'>('group');
  const [submitting,setSubmitting]=useState(false);
  const chartId=useId().replaceAll(':','');
  const {job,busy,error:pollError,reserve,attach,discard}=useLiveJob<Analysis>('bmw-live-market-job');
  useEffect(()=>{setRegion(scope.market);},[scope.market]);
  useEffect(()=>{
    const abort=new AbortController();setError('');setData(null);setSignalIndex(0);
    const params=new URLSearchParams({vehicle:scope.vehicle,market:region,powertrain:scope.powertrain});
    Promise.all([api<MarketDashboard>(`/market/dashboard?${params}`,{signal:abort.signal}),api<Runtime>('/market/status',{signal:abort.signal})]).then(([d,r])=>{if(!abort.signal.aborted){setData(d);setRuntime(r);}}).catch(e=>{if(!abort.signal.aborted)setError(e.message);});
    return ()=>abort.abort();
  },[region,scope.vehicle,scope.powertrain,refresh]);
  const source=(id?:string)=>data?.evidence.find(e=>e.id===id);
  const signals=data?.signals.filter(s=>s.topic===topic)||[];
  const signal=signals[Math.min(signalIndex,Math.max(0,signals.length-1))];
  const group=data?.series.find(s=>s.level==='group');
  const model=data?.series.find(s=>s.level==='model');
  const series=chartLevel==='group'?group:model;
  const points=series?.points.filter(p=>p.kind!=='planning')||[];
  const planning=model?.points.find(p=>p.kind==='planning');
  const yoy=group?.yoy;
  const result=job?.status==='succeeded' && job.kind==='market_analysis'?job.result:null;
  const matches=result && result.scope.market===region && result.scope.vehicle===scope.vehicle && result.scope.powertrain===scope.powertrain && result.scope.horizon===scope.horizon && result.market_topic===topic;
  const rec=matches?result.recommendations[0]:null;
  async function analyze() {
    if(submitting||busy)return;
    setSubmitting(true);setRequestError('');const id=reserve();
    try {
      attach(await post<Job<Analysis>>('/market/jobs',{client_job_id:id,analysis_id:crypto.randomUUID(),scope:{vehicle:scope.vehicle,market:region,powertrain:scope.powertrain,horizon:scope.horizon,topic:topic==='Digital experience'?'Displays':topic==='Regional demand'?'Market priorities':topic},market_topic:topic}));
    } catch(e) {if(e instanceof LiveApiError && [409,422,503].includes(e.status))discard();setRequestError(e instanceof Error?e.message:'Analysis could not start.');}
    finally {setSubmitting(false);}
  }
  return <div className="mt-page">
    <header className="mt-hero"><div className="mt-hero-copy"><div className="mt-kicker"><span/> INTELLIGENCE / 03 <span className="mt-kicker-divider">MARKET TRENDS</span></div><h1>See the shift.<br/><span>Decide what’s next.</span></h1><p>Understand what’s moving the industry.<br/>Find what matters for your next BMW.</p><div className="mt-hero-meta"><span className="mt-status"><i className={runtime?.analysis_ready?'ready':''}/>{runtime?.analysis_ready?`${runtime.model} · ready`:'Checking local agent'}</span><span>Evidence snapshot · {data?.as_of||'loading'}</span></div></div><RadarVisual region={region}/></header>
    <section className="mt-controls" aria-label="Market analysis scope"><div className="mt-region-tabs" aria-label="Choose market">{regions.map(r=><button key={r} aria-pressed={region===r} onClick={()=>setRegion(r)}>{r}</button>)}</div><span className="mt-scope">BMW {scope.vehicle} <span> / {scope.powertrain}</span></span><button className="mt-refresh" aria-label="Refresh market data" onClick={()=>setRefresh(n=>n+1)}><RefreshCw size={16}/></button></section>
    <nav className="mt-topics" aria-label="Choose trend">{topics.map(({name,icon:Icon})=><button key={name} aria-pressed={topic===name} onClick={()=>{setTopic(name);setSignalIndex(0);}}><Icon size={16}/>{name}</button>)}</nav>
    {error && <div className="mt-error" role="alert">{error}<button onClick={()=>setRefresh(n=>n+1)}>Try again</button></div>}
    {!error&&!data && <div className="mt-loading" role="status"><LoaderCircle className="mt-spin"/>Loading sourced market intelligence…</div>}
    {data && <>
      <div className="mt-signal-grid" key={`${topic}-${region}`}>
        <section className="mt-signal-card"><div className="mt-card-eyebrow"><span><Sparkles size={14}/> {topic==='Regional demand'?'THE REGIONAL PICTURE':'INDUSTRY SIGNAL'}</span><span className="mt-type">{signal?.kind || 'Historical context'}</span></div>
          <h2>{signal?.title || `${region}, in perspective.`}</h2>
          <div className="mt-signal-number"><strong>{signal?.headline || (yoy!=null?`${yoy>0?'+':''}${yoy.toFixed(1)}%`:'—')}</strong><span>{signal?.unit || 'BMW Group delivery change · 2024–2025'}</span></div>
          <p className="mt-signal-summary">{signal?.summary || (topic==='Regional demand'?source(group?.evidence_id)?.passage:'No reviewed industry signal for this topic in this region. The agent can inspect broader context and identify what evidence is missing.')}</p>
          <div className="mt-source-meta"><span>{signal?.geography || region}</span><span>{signal?.period || '2024–2025'}</span></div>
          {signal && <div className="mt-implication"><span>QUESTION FOR BMW</span><p>{signal.implication}</p></div>}
          {signals.length>1 && <div className="mt-signal-options" aria-label="Related signals">{signals.map((s,i)=><button key={s.id} aria-pressed={i===signalIndex} onClick={()=>setSignalIndex(i)}>{s.title}</button>)}</div>}
          <SourceDetails source={source(signal?.evidence_id || group?.evidence_id)}/>
        </section>
        <aside className="mt-context-card"><span className="mt-card-eyebrow">KEEP THE CONTEXT</span><div className="mt-context-icon"><Globe2 size={24}/></div><h2>What’s happening<br/>for BMW?</h2><p className="mt-context-label">BMW Group deliveries · {region}</p><strong className="mt-context-value">{group?number(group.points.at(-1)!.value):'—'}</strong><span className="mt-context-year">vehicles in 2025</span><div className={`mt-change ${(yoy??0)<0?'negative':''}`}>{(yoy??0)<0?<ArrowDownRight size={20}/>:<ArrowUpRight size={20}/>}<strong>{yoy!=null?`${yoy>0?'+':''}${yoy.toFixed(1)}%`:'Unavailable'}</strong><span>vs. 2024</span></div><p className="mt-context-note">Group-wide context. This does not measure demand for BMW {scope.vehicle} or prove that a feature caused sales.</p></aside>
      </div>
      <section className="mt-chart-panel"><div className="mt-section-head"><div><span className="mt-card-eyebrow">THE DIRECTION OF TRAVEL</span><h2>Put the signal in perspective.</h2></div><div className="mt-chart-toggle"><button aria-pressed={chartLevel==='group'} onClick={()=>setChartLevel('group')}>BMW Group</button><button aria-pressed={chartLevel==='model'} onClick={()=>setChartLevel('model')}>Model inputs</button></div></div><div className="mt-chart-legend"><span><i/>{series?.title} · {region}</span><small>{chartLevel==='group'?'Reported annual deliveries':'Challenge-supplied volumes · all powertrains'}</small></div>
        <div className="mt-chart" role="img" aria-label={`${series?.title}: ${points.map(p=>`${p.year}: ${p.value} vehicles`).join(', ')}`}><ResponsiveContainer width="100%" height="100%"><AreaChart data={points} margin={{top:20,right:12,bottom:4,left:4}}><defs><linearGradient id={chartId} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8cbaff" stopOpacity={0.28}/><stop offset="100%" stopColor="#8cbaff" stopOpacity={0}/></linearGradient></defs><CartesianGrid vertical={false} stroke="rgba(170,190,220,.1)" strokeDasharray="3 6"/><XAxis dataKey="year" axisLine={false} tickLine={false} tick={{fill:'#8195ac',fontSize:12}} tickMargin={14}/><YAxis axisLine={false} tickLine={false} tickFormatter={number} tick={{fill:'#8195ac',fontSize:11}} width={50}/><Tooltip contentStyle={{background:'#111f30',border:'1px solid #344861',borderRadius:12,color:'#fff'}} formatter={(value)=>[Number(value).toLocaleString()+' vehicles','Volume']}/><Area type="linear" dataKey="value" stroke="#9ebfff" strokeWidth={2.5} fill={`url(#${chartId})`} dot={{r:4,fill:'#bfd3ff',stroke:'#0b1522',strokeWidth:3}} activeDot={{r:6}} isAnimationActive={false}/></AreaChart></ResponsiveContainer></div>
        {chartLevel==='model' && planning && <div className="mt-planning"><span>2030 supplied planning input</span><strong>{planning.value.toLocaleString()} vehicles</strong><small>Future assumption · deliberately separate from history</small></div>}
        <SourceDetails source={source(series?.evidence_id)}/>
      </section>
      <section className="mt-agent-action"><div className="mt-agent-emblem"><Radar size={28}/></div><div><span className="mt-card-eyebrow">YOUR MARKET SPECIALIST</span><h2>Turn the trend into a better question.</h2><p>Investigate relevance, challenge assumptions, and propose the next test.</p></div><button className="mt-primary" disabled={busy||submitting||!runtime?.analysis_ready} onClick={analyze}>{busy||submitting?<LoaderCircle className="mt-spin" size={17}/>:<Sparkles size={17}/>}Analyze this trend <ArrowRight size={17}/></button></section>
      {(requestError||pollError) && <div className="mt-error" role="alert">{requestError||pollError}</div>}
      {(busy||job?.status==='failed') && <div className="mt-job" role="status">{busy&&<LoaderCircle className="mt-spin" size={18}/>}<div><strong>{job?.phase || 'Submitting research…'}</strong><p>{job?.error || 'Real local inference. You can leave this page and return to the saved job.'}</p><small>{job?.request.scope.market} · {job?.request.scope.topic}</small></div></div>}
      {result&&!matches && <p className="mt-muted">Your saved result belongs to another scope. Return to {result.scope.market} / {result.market_topic}, or run a new analysis.</p>}
      {matches&&rec&&<section className="mt-result"><div className="mt-section-head"><div><span className="mt-card-eyebrow"><Check size={14}/> SAVED AGENT ANALYSIS</span><h2>A direction to investigate.</h2></div><span className="mt-type">{result.position.stance.replaceAll('_',' ')}</span></div><p className="mt-result-lead">{rec.proposed_change}</p><p>{result.position.rationale}</p><div className="mt-result-pair"><div><span className="mt-card-eyebrow">POSSIBLE UPSIDE</span>{rec.positive_effects.map((e,i)=><p key={i}>{e.description}</p>)}</div><div><span className="mt-card-eyebrow">THE TRADE-OFF</span>{rec.negative_effects.map((e,i)=><p key={i}>{e.description}</p>)}</div></div><div className="mt-validation"><strong>Test before committing</strong>{rec.validation_needed.map(v=><p key={v}>{v}</p>)}<small>Benefits and risks are hypotheses, not measured outcomes.</small></div><details className="mt-source"><summary>Evidence, counterpoint & research steps <ChevronDown size={14}/></summary><div><p>{rec.rationale}</p>{result.position.claims.map(c=><div className="mt-result-fact" key={c.id}><p>{c.text}</p>{c.evidence_ids.map(id=><SourceDetails key={id} source={result.evidence.find(e=>e.id===id)}/>)}</div>)}<ol>{result.research_steps.map((s,i)=><li key={i}>{s}</li>)}</ol>{result.uncertainties.map(u=><p key={u}>{u}</p>)}</div></details><div className="mt-result-footer"><span>Saved locally · {result.model}</span><Link className="mt-primary" to={`/council?agent=market&source_run=${result.run_id}`}>Bring to council <ArrowRight size={17}/></Link></div></section>}
      <details className="mt-coverage"><summary>What this evidence covers <ChevronDown size={14}/></summary><ul>{data.coverage.map(c=><li key={c}>{c}</li>)}</ul><p>No news crawl runs automatically. Refresh reloads the reviewed catalog.</p></details>
    </>}
  </div>;
}
EOF",max_output_tokens:300}));

