  await page.screenshot({path:'/tmp/market-mobile.png',fullPage:true,animations:'disabled'});
  await page.emulateMedia({reducedMotion:'reduce'});
  expect(await page.locator('.mt-orbit-outer').evaluate(el=>getComputedStyle(el).animationName)).toBe('none');
  await page.setViewportSize({width:1440,height:1050});
  expect(debatePosts).toBe(0);
  if(env.LIVE_OLLAMA==='1') {
    if(env.RESUME_MARKET_JOB) await page.evaluate(id=>localStorage.setItem('bmw-live-market-job',id),env.RESUME_MARKET_JOB);
    else await page.getByRole('button',{name:'Analyze this trend'}).click();
    await page.reload();
    async function finish(key:string,timeout:number) {
      await expect.poll(async()=>{
        const id=await page.evaluate(k=>localStorage.getItem(k),key);
        if(!id)return 'pending';
        const response=await page.request.get(`/api/jobs/${id}`);
        if(response.status()===404)return 'pending';
        const job=await response.json();
        if(job.status==='failed')throw new Error(job.error);
        return job.status;
      },{timeout,intervals:[2500]}).toBe('succeeded');
    }
    await finish('bmw-live-market-job',600000);
    await expect(page.getByRole('link',{name:'Bring to council'})).toBeVisible();
    await page.screenshot({path:'/tmp/market-result.png',fullPage:true,animations:'disabled'});
    expect(debatePosts).toBe(0);
    await page.getByRole('link',{name:'Bring to council'}).click();
    await expect(page.getByRole('button',{name:'Start live debate'})).toBeEnabled();
    expect(debatePosts).toBe(0);
    await page.getByRole('button',{name:'Start live debate'}).click();
    await page.reload();
    await finish('bmw-live-debate-job',950000);
    await expect(page.locator('.lc-turn')).toHaveCount(6);
    await expect(page.locator('.lc-market').last()).toContainText('Responding to:');
    await expect(page.locator('.lc-challenge')).not.toHaveCount(0);
    await page.screenshot({path:'/tmp/market-council.png',fullPage:true,animations:'disabled'});
    const saved=await page.getByRole('link',{name:'Link to this saved debate'}).getAttribute('href');
    console.log('SAVED DEBATE',saved);
    console.log('MARKET JOB',await page.evaluate(()=>localStorage.getItem('bmw-live-market-job')));
    await page.goto(saved!);
    await expect(page.locator('.lc-turn')).toHaveCount(6);
    expect(debatePosts).toBe(1);
  }
  expect(errors).toEqual([]);
});
