.mt-laser-haze{position:absolute;top:0;right:-70px;width:240px;height:380px;background:radial-gradient(ellipse,#1c69d42b,transparent 65%);transform:rotate(-30deg)}
.mt-agent{min-width:0;padding:32px 32px 23px;border-left:1px solid var(--mt-line);display:flex;flex-direction:column;background:linear-gradient(145deg,#101722,#0c111a)}
.mt-agent-heading>svg{color:#6584ac;stroke-width:1.2}
.mt-agent-intro{flex:1;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;padding:20px 0 28px}
.mt-agent-mark{display:flex;gap:5px;margin-bottom:22px;height:23px;transform:skew(-28deg)}
.mt-agent-mark i{width:5px;background:#84c3ff;box-shadow:0 0 13px #3083e34d}
.mt-agent-mark i:nth-child(2){background:#3687ed}
.mt-agent-mark i:nth-child(3){background:#124384}
.mt-agent-intro h2{font-size:clamp(26px,2.7vw,37px);font-weight:450;letter-spacing:-1.3px;line-height:1.17}
.mt-agent-intro p{margin-top:18px;max-width:330px;color:#9eacbf;font-size:12px;line-height:1.8}
.mt-agent-intro>span{margin-top:17px;font-size:10px;color:#667b99}
.mt-agent-actions{display:grid;gap:10px;margin-top:auto;padding-top:22px}
.mt-primary{display:flex;align-items:center;justify-content:space-between;gap:12px;border:1px solid #5499f6;border-radius:3px;background:linear-gradient(110deg,#1c69d4,#1957ae);color:white!important;text-decoration:none;padding:14px 17px;font-size:12px!important;font-weight:500;transition:background .2s,box-shadow .25s;box-shadow:0 4px 20px #1c69d416}
.mt-primary:hover{background:linear-gradient(110deg,#2879e7,#1c69d4);box-shadow:0 4px 24px #1c69d444}
.mt-agent-actions>small{text-align:center;color:#75859b;font-size:9px;line-height:1.5}
.mt-rerun{background:none;border:0;color:#9ab9e0;font-size:10px!important;padding:3px 0}
.mt-result{padding-top:24px;flex:1;min-width:0}
.mt-result-state{font-size:9px;color:#88b2e9;line-height:1.5;display:block;margin-bottom:11px}
.mt-result h2{font-size:20px;font-weight:450;letter-spacing:-.45px;line-height:1.4}
.mt-result-tabs{display:flex;gap:21px;border-bottom:1px solid var(--mt-line);margin-top:23px}
.mt-result-tabs button{border:0;background:none;color:#7e8ea5;padding:10px 0;font-size:11px;position:relative}
.mt-result-tabs button[aria-pressed=true]{color:#dbe9ff}
.mt-result-tabs button[aria-pressed=true]:after{position:absolute;content:"";bottom:0;left:0;right:0;height:1px;background:#75adfa}
.mt-result-detail{padding:15px 0 8px;min-height:105px;font-size:12px;line-height:1.7;color:#bbc8da}
.mt-result-detail small{display:block;color:#7087a5;font-size:9px;margin-top:10px}
.mt-page details>summary{display:flex;justify-content:space-between;align-items:center;gap:10px;cursor:pointer;list-style:none}
.mt-page details>summary:after,.mt-page details>summary::-webkit-details-marker{display:none}
.mt-page details[open]>summary>svg,.mt-context[open]>summary .mt-context-preview>svg{transform:rotate(180deg)}
.mt-reasoning{margin-top:4px;color:#99acc7;font-size:11px;line-height:1.8}
.mt-reasoning summary{font-size:10px;padding:9px 0;border-top:1px solid var(--mt-line)}
.mt-reasoning p{margin:12px 0}
.mt-fact{border-top:1px solid var(--mt-line);padding-top:5px}
.mt-context{border-top:1px solid var(--mt-line);scroll-margin-top:80px}
.mt-context>summary{padding:20px 27px;color:#c8d3e2;font-size:12px}
.mt-context>summary>span:first-child{display:flex;gap:17px;align-items:center}
.mt-context summary small{font-size:10px;color:#6e819e;font-weight:400}
.mt-context-preview{display:flex;align-items:center;gap:16px;font-size:10px;color:#7c91af}
.mt-change{font-size:13px;font-weight:450;color:#bcdbff}
.mt-context-body{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);border-top:1px solid var(--mt-line)}
.mt-chart-panel,.mt-source-panel{padding:26px;min-width:0}
.mt-source-panel{border-left:1px solid var(--mt-line)}
.mt-section-head{display:flex;justify-content:space-between;align-items:center;gap:12px}
.mt-section-head h2,.mt-source-panel h2{font-size:15px;font-weight:450;letter-spacing:-.2px}
.mt-chart-toggle{display:flex;border:1px solid var(--mt-line);border-radius:3px;padding:3px}
.mt-chart-toggle button{background:none;color:#8ba1bf;padding:6px 8px;border:0;font-size:9px}
.mt-chart-toggle button[aria-pressed=true]{background:#20334e;color:#ecf3ff}
.mt-chart-legend{display:flex;gap:10px;flex-wrap:wrap;justify-content:space-between;font-size:10px;color:#99b1d2;margin:20px 0 10px}
.mt-chart-legend small{font-size:9px;color:#798eae}
.mt-chart{height:190px;width:100%;min-width:0}
.mt-planning{border:1px dashed #4c6b9355;border-radius:3px;padding:10px;display:flex;gap:8px;flex-wrap:wrap;font-size:10px;color:#a6bcda;margin-top:10px}
.mt-planning small{width:100%;font-size:9px;color:#7b91af}
.mt-source{font-size:11px;line-height:1.7;color:#91a8c8;border-top:1px solid var(--mt-line);margin-top:13px;overflow-wrap:anywhere}
.mt-source summary{padding:13px 0;color:#b9cee9;font-size:10px}
.mt-source>div{padding-bottom:12px}
.mt-source p{margin:7px 0}
.mt-source a{display:inline-flex;align-items:center;gap:5px}
.mt-source ul{padding-left:17px}
.mt-source li{margin-top:6px}
.mt-error{color:#e7c9c9;background:#4d273322;padding:15px;font-size:11px;line-height:1.6;border:1px solid #b67c8726;margin:12px}
.mt-error button{margin-left:10px;color:#d5e8ff;background:none;border:0;text-decoration:underline}
.mt-agent .mt-error{margin:15px 0 0}
.mt-loading{padding:80px 25px;display:flex;justify-content:center;align-items:center;gap:12px;color:#a1b9db;font-size:12px}
.mt-job{margin-top:18px;display:flex;gap:10px;align-items:flex-start;color:#9bbceb;font-size:11px;line-height:1.6}
.mt-job svg{flex-shrink:0;margin-top:2px}
.mt-job strong{font-weight:500;color:#ceddf4}
.mt-job p{margin:6px 0;font-size:10px}
.mt-job small{color:#7088a8;font-size:9px}
.mt-saved-note{font-size:10px;color:#8a9db9;line-height:1.6;margin-top:14px!important}
.mt-footnote{display:flex;justify-content:space-between;gap:15px;font-size:9px;color:#62748f;padding:16px 2px}
.mt-spin{animation:mt-spin 1.5s linear infinite}
.app-shell:has(.mt-page) .session-dot,.workspace:has(.mt-page) .session-dot{background:#83baff;box-shadow:0 0 10px #1c69d444}
