/** Shared character silhouette; all surfaces and role accessories are real 3D meshes. */
export function CouncilCharacter({ agent, state, paused }: { agent: AgentId; state: AgentState; paused: boolean }) {
  const eyes = useRef<Group>(null);
  const time = useRef(0);
  const active = ["speaking","challenging","evaluating"].includes(state);
  const geometry = useMemo(() => {
    const sphere = new SphereGeometry(.57,64,48);
    const vertices = sphere.getAttribute("position");
    const colors = new Float32Array(vertices.count*3);
    const [base,accent,warm] = palettes[agent].map(color => new Color(color));
    const c = new Color();
    for (let i=0;i<vertices.count;i++) {
      const x=vertices.getX(i)/.57, y=vertices.getY(i)/.57, z=vertices.getZ(i)/.57;
      const violet=Math.exp(-((x-.65)**2+(y-.25)**2+(z-.45)**2)*2);
      const gold=Math.exp(-((x+.55)**2+(y+.45)**2+(z-.65)**2)*2.4);
      c.copy(base).lerp(accent,violet*.86).lerp(warm,gold*.86);
      colors.set([c.r,c.g,c.b],i*3);
    }
    sphere.setAttribute("color",new Float32BufferAttribute(colors,3));
    return sphere;
  },[agent]);
  useEffect(() => () => geometry.dispose(),[geometry]);
  useFrame((_,delta) => {
    if(paused || !eyes.current) return;
    time.current += Math.min(delta,.05);
    const phase=(time.current + Object.keys(palettes).indexOf(agent)*1.17)%5.3;
    const blink=phase>4.95 ? Math.max(.07,Math.abs(phase-5.12)/.17) : 1;
    eyes.current.scale.y=blink*(active ? .92+.08*Math.sin(time.current*4) : 1);
  });
  return <group name={`${agent}-character`}>
    <mesh geometry={geometry}>
      <meshPhysicalMaterial vertexColors metalness={.35} roughness={.26} clearcoat={1} clearcoatRoughness={.14} iridescence={.22} iridescenceIOR={1.3} />
    </mesh>
    <group rotation={[-.12,0,0]}>
      <group ref={eyes} position={[0,.055,.525]}>
        {[-1,1].map(side => <RoundedBox key={side} position={[side*.215,0,0]} rotation={[0,side*.32,side*-.06]} args={[.27,agent==="competitor"?.085:.115,.045]} radius={.04} smoothness={4}><Glow /></RoundedBox>)}
      </group>
      {[-1,1].map(side => <mesh key={side} position={[side*.23,.235,.469]} rotation={[0,side*.25,Math.PI/2+side*(state==="challenging"?-.18:.08)]}><capsuleGeometry args={[.014,.1,4,12]} /><meshStandardMaterial color={agent==="judge"?"#0864c6":"#283e6e"} roughness={.3} /></mesh>)}
      <Line points={[[-.07,-.16,.541],[0,-.18,.548],[.07,-.16,.541]] color="#edf0e7" lineWidth={1.25} transparent opacity={.65} />
    </group>
    <Accessories agent={agent} active={active} paused={paused} />
  </group>;
}
